<?php include 'verifica_login.php'; include 'conexao.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id||$id<1)die('ID inválido.');$q=mysqli_query($conexao,"SELECT arquivo FROM trabalhos_academicos WHERE id_trabalho=$id");$row=$q?mysqli_fetch_assoc($q):null;$ok=mysqli_query($conexao,"DELETE FROM trabalhos_academicos WHERE id_trabalho=$id");if(!$ok)die('Não foi possível excluir o trabalho: '.htmlspecialchars(mysqli_error($conexao)));if($row&&!empty($row['arquivo'])){@unlink(__DIR__.'/uploads/trabalhos/'.$row['arquivo']);}header('Location: lista_TA.php');exit;
